// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(target != address(c));
        amount = bound(amount, 0, 1 ether);

        // fund c through its payable fallback (as test contract, accept ETH first)
        vm.deal(address(this), amount);
        (bool okSend, ) = address(c).call{value: amount}("");
        assertTrue(okSend);
        assertEq(address(c).balance, amount);

        uint256 balBefore = address(c).balance;

        vm.prank(c.owner());
        c.sendMoney(target, amount);

        assertTrue(address(c).balance == balBefore - amount);
    }
}

contract Recorder {
    uint256 public received;
    fallback() external payable { received += msg.value; }
}
